\label{asm:classical}
    The coefficients satisfy
    \[
        b\in C 
  \def#1{n+1} 
  \def0{0} 
  \ifx#10\else^{n+1}\fi
_{w_{1}}({\mathbb R}^d;{\mathbb R}^d),
        \qquad
        \sigma\in C 
  \def#1{n+1} 
  \def0{0} 
  \ifx#10\else^{n+1}\fi
_{w_{1}}({\mathbb R}^d;({\mathbb R}^d)^m),
    \]
    and
    \[
        \|b\|_{C 
  \def#1{n+1} 
  \def0{0} 
  \ifx#10\else^{n+1}\fi
_{w_{1}}}\le B,
        \qquad
        \|\sigma\|_{C 
  \def#1{n+1} 
  \def0{0} 
  \ifx#10\else^{n+1}\fi
_{w_{1}}}\le S,
    \]
    for some $n \in {\mathbb N}$.

\label{thm:sde-A}
Fix $n \in {\mathbb N}$ and let Assumption~\ref{asm:classical} hold. Then for every $r \in \{1,\dots,n\}$ and $p \ge 2$, there is a constant $c > 0$ such that for all $x \in {\mathbb R}^d$ and all $v_1,\dots,v_r \in {\mathbb R}^d$,
\begin{equation}\label{eq:sde-A-bound}
    {\mathbb{E}}_x \big| w_{r-1}(X_t)\, Y^{(r)}_t(x)\,[v_1,\dots,v_r] \big|^p
    \le c\,(e^{ct}-1)\,|v_1|^p \cdots |v_r|^p, \qquad r \ge 2,
\end{equation}
and the case $r=1$ satisfies ${\mathbb{E}}_x|Y^{(1)}_t(x) v|^p \le |v|^p\,e^{ct}$.

\label{thm:sde-B}
Fix $n \in {\mathbb N}$ and let Assumption~\ref{asm:bounded_derivatives} hold. Then, for every $r \in \{1,\dots,n\}$ and $p \ge 2$, there is a constant $c > 0$ such that, uniformly in $x \in {\mathbb R}^d$,
\begin{equation}\label{eq:sde-B-bound}
    {\mathbb{E}}\,\big| Y^{(r)}_t(x)\,[v_1,\dots,v_r] \big|^p
    \le c\,(e^{ct}-1)\,|v_1|^p\cdots|v_r|^p, \qquad r \ge 2,
\end{equation}
for all $v_1,\dots,v_r \in {\mathbb R}^d$, and the case $r=1$ satisfies ${\mathbb{E}}|Y^{(1)}_t(x) v|^p \le |v|^p\,e^{ct}$.

\label{rem:bounded_derivatives_generator_counterexample}
We show that the generator mapping ${\@fontswitch\relax\mathcal L} \colon C 
  \def#1{n} 
  \def0{0} 
  \ifx#10\else^{n,\mathrm{bd}}\fi
_{w_2,\infty}\to C 
  \def#1{n-2} 
  \def0{0} 
  \ifx#10\else^{n-2,\mathrm{bd}}\fi
_{w_2,\infty}$ fails already for $n=3$.
Already in dimension $d=1$, take $b(x)=x$ and $\sigma(x)=1$, so that Assumption~\ref{asm:bounded_derivatives} holds. Choose $\eta\in C_c^\infty({\mathbb R})$ with $\eta'(0)\ne 0$ and ${\rm supp} \, \eta \subseteq [-1,1]$. We set
\[
h(x):=\sum_{k=1}^\infty 4^{-k}\eta(x-4^k),\qquad \varphi(x):=\int_0^x h(y)\,dy .
\]
Then $\varphi$ is bounded, $\varphi'=h$, and all higher derivatives of $\varphi$ vanish at infinity. Thus $\varphi\in C 
  \def#1{n} 
  \def0{0} 
  \ifx#10\else^{n,\mathrm{bd}}\fi
_{w_2,\infty}({\mathbb R})$ for every $n$. However, for ${\@fontswitch\relax\mathcal L}\varphi=x\varphi'+\frac12\varphi''$,
\[
({\@fontswitch\relax\mathcal L}\varphi)'(4^k)=\varphi'(4^k)+4^k\varphi''(4^k)+\frac12\varphi'''(4^k)\to \eta'(0)\ne 0 .
\]
Consequently ${\@fontswitch\relax\mathcal L}\varphi\notin C 
  \def#1{1} 
  \def0{0} 
  \ifx#10\else^{1,\mathrm{bd}}\fi
_{w_2,\infty}({\mathbb R})$.

\label{lemm:Lyapunov}
    Let \eqref{eq:Lipschitz} hold. Then, for any $\alpha \in {\mathbb R}$, there is $c_\alpha>0$ such that
    \begin{equation}
        \label{eq:Lyapunov}
        {\@fontswitch\relax\mathcal L} w_\alpha(x) \leq c_\alpha w_\alpha(x)
    \end{equation}

\label{lemm:weighted_feller}
Assume the Lipschitz condition \eqref{eq:Lipschitz} holds. Then, for every $\alpha\in{\mathbb R}$, $t\ge0$, and $f\inC 
  \def#1{0} 
  \def0{0} 
  \ifx#10\else^{0}\fi
_{w_{\alpha}}({\mathbb R}^d)$, the map $x\mapsto P_tf(x)$ is continuous. Moreover, if \(g\in C_c({\mathbb R}^d)\), then \(P_tg\in C_\infty({\mathbb R}^d)\) for each \(t\ge0\), and \(P_tg\to g\) uniformly on compact subsets of \({\mathbb R}^d\) as \(t\downarrow0\).

Let \(x_j\to x\). The Lipschitz SDE estimate from \eqref{eq:Lipschitz} gives \(X_t(x_j)\to X_t(x)\) in probability, hence \(f(X_t(x_j))\to f(X_t(x))\) in probability. For large \(j\) the points \(x_j\) lie in a compact set. Since \(|f|\le\|f\|_{C 
  \def#1{0} 
  \def0{0} 
  \ifx#10\else^{0}\fi
_{w_{\alpha}}}w_\alpha\), the family \(\{f(X_t(x_j))\}\) is bounded when \(\alpha\le0\); when \(\alpha>0\), choose \(q>1\) with \(q\alpha\ge2\), and \eqref{eq:power_growth_SDE} gives \(\sup_j{\mathbb{E}}|f(X_t(x_j))|^q<\infty\). Vitali's theorem then yields \(P_tf(x_j)\to P_tf(x)\). For \(g\in C_c({\mathbb R}^d)\) with \(K=\operatorname{supp}g\), the \(C_0\)-Feller property for globally Lipschitz, linearly growing SDEs gives \({\mathbb P}_x(X_t\in K)\to0\) as \(|x|\to\infty\), so \(|P_tg(x)|\le\|g\|_\infty{\mathbb P}_x(X_t\in K)\to0\). For local uniform convergence as \(t\downarrow0\), fix a compact \(K\) and \(\varepsilon>0\). Uniform continuity of \(g\) gives \(\delta>0\) with \(|g(y)-g(x)|<\varepsilon\) for \(|x-y|<\delta\). The same SDE estimate gives \(\sup_{x\in K}{\mathbb P}(|X_t(x)-x|\ge\delta)\to0\), hence \(\limsup_{t\downarrow0}\sup_{x\in K}|P_tg(x)-g(x)|\le\varepsilon\); let \(\varepsilon\downarrow0\).

\label{lemm:invariant}
Assume \eqref{eq:Lipschitz} holds. Then, for all $\alpha \in \mathbb{R}$, the spaces $C 
