\label{theo:deriv_exist}
    Under Assumption \ref{asm:classical}, the map $x\mapsto X_t(x)$ admits a modification continuously differentiable with respect to $x$, and the first derivative $\mathrm{D} X_t(x)$ is the unique strong solution of the SDE
    \begin{equation}
        \label{eq:jet}
        \mathrm{D} X_t(x)=I+\int_0^t \mathrm{D} b\bigl(X_s(x)\bigr) \,\mathrm{D} X_s(x)\,ds+\sum_{l=1}^m \int_0^t \mathrm{D} \sigma_l\bigl(X_s(x)\bigr) \,\mathrm{D} X_s(x)\,dW_s^l,
    \end{equation}
    where $I[u] = u$ is the identity mapping on ${\mathbb R}^d$.
    Moreover, for every $u \in {\mathbb R}^d$ and $p \ge 2$,
    \[
        {\mathbb{E}} \big|\mathrm{D} X_t(x)[u]\big|^p < \infty.
    \]

Let $X, Y, Z$ be Banach spaces and let $f \colon X \to Y$,
    $g \colon Y \to Z$.
    Let $x \in X$ and set $y = f(x)$.
    Assume that $f$ and $g$ have continuous derivatives up to order $m$ in a neighbourhood of $x$ and $y$, respectively. Then, for $v_1,\dots,v_m\in X$,
    \begin{equation}
    \begin{aligned}
        \mathrm{D}^m (g \circ f)(x)[ v_1, \dots, v_m]
        &=
        \sum_{k=1}^{m}
        \ \sum_{P \in \mathcal{P}(m,k)}
        \mathrm{D}^k g\bigl( y \bigr)
        \Bigl[
            \mathrm{D}^{|P_1|} f(x)\bigl[ \bigvee_{i \in P_1} v_i \bigr],
            \dots,
            \mathrm{D}^{|P_k|} f(x)\bigl[ \bigvee_{i \in P_k} v_i \bigr]
        \Bigr].
    \end{aligned}
    \end{equation}

\label{prop:higher_jet_sde}
Fix $n\in {\mathbb N}$ and let Assumption~\ref{asm:bounded_derivatives} hold. For $x\in {\mathbb R}^d$, let $X_t(x)$ be the unique strong solution of
\[
dX_t(x)=b(X_t(x))\,dt+\sum_{\ell=1}^m \sigma_\ell(X_t(x))\,dW_t^\ell,
\qquad X_0(x)=x,
\]
where $\sigma_\ell$ denotes the $\ell$-th column of $\sigma$. For $j\ge 1$, define
\[
Y_t^{(j)}(x):=\mathrm{D}_x^j X_t(x)\in \mathfrak L_j({\mathbb R}^d,{\mathbb R}^d).
\]
Then, for every $r\in\{1,\dots,n\}$, the derivative $Y_t^{(r)}(x)$ exists almost surely, is adapted and continuous in $t$, with initial condition \(Y_0^{(1)}=I\) and \(Y_0^{(r)}=0\) for \(r\ge2\), and satisfies
\begin{equation}
\label{eq:higher-jet}
Y_t^{(r)}=Y_0^{(r)}+\int_0^t \mathrm{D}_x^r\!\bigl(b\circ X_s\bigr)\,ds+\sum_{\ell=1}^m \int_0^t \mathrm{D}_x^r\!\bigl(\sigma_\ell\circ X_s\bigr)\,dW_s^\ell.
\end{equation}
Moreover, for every $v_1,\dots,v_r\in {\mathbb R}^d$,
\begin{align}
\label{eq:Faa_di_Bruno_b}
\mathrm{D}_x^r(b\circ X_s)[v_1,\dots,v_r]
&=\sum_{q=1}^r \ \sum_{\pi\in \mathcal P(r,q)}
\mathrm{D}^q b(X_s)\Big[Y_s^{(|B_1|)}[v_{B_1}],\dots,Y_s^{(|B_q|)}[v_{B_q}]\Big],\\
\label{eq:Faa_di_Bruno_sigma}
\mathrm{D}_x^r(\sigma_\ell\circ X_s)[v_1,\dots,v_r]
&=\sum_{q=1}^r \ \sum_{\pi\in \mathcal P(r,q)}
\mathrm{D}^q \sigma_\ell(X_s)\Big[Y_s^{(|B_1|)}[v_{B_1}],\dots,Y_s^{(|B_q|)}[v_{B_q}]\Big].
\end{align}

\label{lemm:multi_d_1st}
    Let \(b\) and the vector fields \(\sigma_1,\dots,\sigma_m\) in \eqref{eq:SDE} have bounded first derivatives. Set
    \[
        B_1 := \sup_{x} \| \mathrm{D} b(x) \|, \qquad
        S_1 := \left(\sum_{\ell=1}^m \sup_x\|\mathrm{D}\sigma_\ell(x)\|^2\right)^{1/2}.
    \]
    Let $Y_t = \mathrm{D} X_t$.
    Then for $p > 0$
    \begin{equation} \label{eq:multi_1st}
        {\mathbb{E}} |Y_t v|^p \leq |v|^p e^{c t},
    \end{equation}
    where
    \begin{eqnarray*}
        c =
        \begin{cases}
            p B_1 + \frac{p(p-1)}{2} S_1^2, \qquad p \ge 2, \\
            \frac{p}{2} \left(2 B_1 +  S_1^2\right), \qquad 0 < p < 2.
        \end{cases}
    \end{eqnarray*}

\label{lemm:normalized_Z_sde}
Let Assumption \ref{asm:classical} hold, \(r\in\{1,\dots,n\}\), and let \(Z_t^{(r)}:=w_{r-1}(X_t)Y_t^{(r)}\) be the normalized $r$-th derivative of the SDE solution. Then
\begin{equation}\label{eq:normalized_Z_sde}
    dZ_t^{(r)}=\bigl(\mathfrak A_t^{(r)}Z_t^{(r)}+\widehat F_t^{(r)}\bigr)\,dt+\sum_{\ell=1}^m\bigl(\mathfrak B_{\ell,t}^{(r)}Z_t^{(r)}+\widehat G_{\ell,t}^{(r)}\bigr)\,dW_t^\ell,
\end{equation}
with \(Z_0^{(1)}=I\), \(Z_0^{(r)}=0\) for \(r\ge2\), and uniformly bounded linear coefficients
\[
\begin{aligned}
    \mathfrak A_t^{(r)}&=\mathrm{D} b(X_t)+\frac{{\@fontswitch\relax\mathcal L} w_{r-1}(X_t)}{w_{r-1}(X_t)}\,I+\sum_{\ell=1}^m\frac{\nabla w_{r-1}(X_t)\sigma_\ell(X_t)}{w_{r-1}(X_t)}\,\mathrm{D}\sigma_\ell(X_t),\\
    \mathfrak B_{\ell,t}^{(r)}&=\mathrm{D}\sigma_\ell(X_t)+\frac{\nabla w_{r-1}(X_t)\sigma_\ell(X_t)}{w_{r-1}(X_t)}\,I.
\end{aligned}
\]
For \(r\ge2\),
\[
    \widehat G_{\ell,t}^{(r)}:=w_{r-1}(X_t)G_{\ell,t}^{(r)},\qquad
    \widehat F_t^{(r)}:=w_{r-1}(X_t)F_t^{(r)}+\sum_{\ell=1}^m\bigl(\nabla w_{r-1}(X_t)\sigma_\ell(X_t)\bigr)G_{\ell,t}^{(r)};
\]
both are zero at \(r=1\). For all \(v_1,\dots,v_r\in{\mathbb R}^d\),
\begin{equation}\label{eq:normalized_Z_rhs_bound}
    |\widehat F_t^{(r)}[v_1,\dots,v_r]|+\sum_{\ell=1}^m|\widehat G_{\ell,t}^{(r)}[v_1,\dots,v_r]|
    \le C\sum_{q=2}^r\sum_{\pi=\{B_1,\dots,B_q\}\in\mathcal P(r,q)}
    \prod_{j=1}^q |Z_t^{(|B_j|)}[v_{B_j}]|.
\end{equation}

\label{lemm:multid}
    Let $b$ and $\sigma$ satisfy Assumption \ref{asm:classical} for $n \geq 2$.
    Then, for every \(r\in\{2,\dots,n\}\), \(p > 0\), and \(v_1,\dots,v_r\in{\mathbb R}^d\),
    \begin{equation} \label{eq:multi_higher}
        {\mathbb{E}}_x |Y_t^{(r)}(x)[v_1,\dots,v_r]|^p \leq \frac{c(e^{c t} - 1)|v_1|^p\cdots |v_r|^p}{(1+ |x|^2)^{p(r-1)/2}},
    \end{equation}
    where $c>0$ is a constant.
    Let \(Z_t^{(r)}=w_{r-1}(X_t)Y_t^{(r)}\). Then, for all \(p\ge2\),
    \begin{equation} \label{eq:higher_Z}
        {\mathbb{E}}_x |Z_t^{(r)}(x)[v_1,\dots,v_r]|^p \leq c (e^{c t} - 1)|v_1|^p\cdots |v_r|^p.
    \end{equation}

The boundedness of \(J_qf\) follows directly from the definition of \(\|f\|_{C 
  \def#1{n} 
  \def0{0} 
  \ifx#10\else^{n}\fi
_{w_{\alpha}}}\). If \(q\le n-1\), then the Leibniz rule gives
\[
    \mathrm{D} J_qf=(\mathrm{D} w_{q-\alpha})\otimes\mathrm{D}^qf+w_{q-\alpha}\mathrm{D}^{q+1}f.
\]
Using \(|\mathrm{D} w_{q-\alpha}|\le Cw_{q-\alpha}w_{-1}\), \(\|\mathrm{D}^qf\|\le \|f\|_{C 
  \def#1{n} 
  \def0{0} 
  \ifx#10\else^{n}\fi
_{w_{\alpha}}}w_{\alpha-q}\), and \(\|\mathrm{D}^{q+1}f\|\le \|f\|_{C 
  \def#1{n} 
  \def0{0} 
  \ifx#10\else^{n}\fi
_{w_{\alpha}}}w_{\alpha-q-1}\), we obtain the required inequality.

\label{lem:J_increment_stochastic}
Let \(n\in{\mathbb N}\), \(\alpha\in{\mathbb R}\), and let Assumption \ref{asm:classical} hold. Let \(f\inC 
  \def#1{n} 
  \def0{0} 
  \ifx#10\else^{n}\fi
_{w_{\alpha}}({\mathbb R}^d)\), and set
\[
    J_qf(x):=w_{q-\alpha}(x)\mathrm{D}^qf(x),\qquad q=0,\dots,n .
\]
Then, for every \(q\le n-1\) and every \(p\ge2\), there is a constant \(C>0\) such that
\begin{equation}\label{eq:J_increment_stochastic}
    {\mathbb{E}}_x\|J_qf(X_t)-J_qf(x)\|^p
    \le C(e^{Ct}-1)\|f\|_{C 
  \def#1{n} 
  \def0{0} 
  \ifx#10\else^{n}\fi
_{w_{\alpha}}}^p .
\end{equation}

The proof has two steps: a moment bound on the normalized displacement \((X_t-x)/w_1(x)\), and a pointwise bound on the increment of \(J_qf\). Combining the two gives the lemma.

\emph{Step 1: displacement moment bound.}
Set \(\Theta_t:=(X_t-x)/w_1(x)\). Since \(X_t=x+w_1(x)\Theta_t\), Assumption~\ref{asm:classical} gives \(\bigl(|b(X_t)|+\|\sigma(X_t)\|\bigr)/w_1(x)\le C(1+|\Theta_t|)\). Apply It\^o's formula to \(V_t^\varepsilon:=(\varepsilon+|\Theta_t|^2)^{p/2}\) for \(\varepsilon\in(0,1]\) and stop at \(\tau_N^\varepsilon:=\inf\{t:V_t^\varepsilon\ge N\}\). Gronwall gives
\[
    {\mathbb{E}}_xV_{t\wedge\tau_N^\varepsilon}^\varepsilon\le \varepsilon^{p/2}e^{Ct}+C(e^{Ct}-1).
\]
Letting \(N\to\infty\) (Fatou) and \(\varepsilon\downarrow0\) yields
\begin{equation}\label{eq:normalized_displacement}
    {\mathbb{E}}_x\Bigl(\tfrac{|X_t-x|}{w_1(x)}\Bigr)^p\le C(e^{Ct}-1).
\end{equation}

\emph{Step 2: pointwise increment bound and combination.}
By Lemma~\ref{lem:J_increment}, \(\|\mathrm{D} J_qf(y)\|\le C\|f\|_{C 
  \def#1{n} 
  \def0{0} 
  \ifx#10\else^{n}\fi
_{w_{\alpha}}}w_{-1}(y)\) and \(\|J_qf\|_\infty\le\|f\|_{C 
  \def#1{n} 
  \def0{0} 
  \ifx#10\else^{n}\fi
_{w_{\alpha}}}\). The gradient bound, used when \(|y-x|\le w_1(x)/2\), together with the sup bound, used otherwise, gives
\[
    \|J_qf(y)-J_qf(x)\|\le C\|f\|_{C 
  \def#1{n} 
  \def0{0} 
  \ifx#10\else^{n}\fi
_{w_{\alpha}}}\Bigl(\tfrac{|y-x|}{w_1(x)}\wedge1\Bigr).
\]
Applying this with \(y=X_t\), using \((a\wedge1)^p\le a^p\), and invoking \eqref{eq:normalized_displacement}, we obtain \eqref{eq:J_increment_stochastic}.

\label{lem:weighted_product_multi}
Let Assumption~\ref{asm:classical} hold, \(r_1,\dots,r_k\in\{1,\dots,n\}\) with \(\sum_ir_i\le n\), \(\beta\in{\mathbb R}\), \(p\ge2\), and
\[
    R_t^\beta:=\frac{w_\beta(X_t)}{w_\beta(x)},\qquad
    U_t:=\bigotimes_{i=1}^k Z_t^{(r_i)}[v_i],
    \qquad v_i\in({\mathbb R}^d)^{r_i},\ |v_{i,a}|\le1.
\]
There is \(C>0\) such that, for all \(t\ge0\),
\begin{equation}\label{eq:weighted_product_multi}
    {\mathbb{E}}_x\left|R_t^\beta U_t\right|^p
    \le
    \begin{cases}
    Ce^{Ct}, & \max_ir_i=1,\\[1.1ex]
    C(e^{Ct}-1), & \max_ir_i\ge2.
    \end{cases}
\end{equation}

\label{prop:weighted_non_singleton_cancellation}
Let Assumption \ref{asm:classical} hold. Fix \(r\in\{2,\dots,n\}\), let \(\pi=\{B_1,\dots,B_q\}\in\mathcal P(r,q)\) be a non-singleton partition, and write \(s_j=|B_j|\). Then, for every \(f\inC 
  \def#1{n} 
  \def0{0} 
  \ifx#10\else^{n}\fi
_{w_{\alpha}}({\mathbb R}^d)\),
\[
\sup_{|v_1|,\dots,|v_r|\le1}
\left|
{\mathbb{E}}_x\left[
\frac{w_{\alpha-r}(X_t)}{w_{\alpha-r}(x)}
J_qf(X_t)
\big[
Z_t^{(s_1)}[v_{B_1}],\dots,Z_t^{(s_q)}[v_{B_q}]
\big]\right]\right|
\le C(e^{Ct}-1)\|f\|_{C 
  \def#1{n} 
  \def0{0} 
  \ifx#10\else^{n}\fi
_{w_{\alpha}}}.
\]

\label{lem:weighted_density}
For every \(n\in{\mathbb N}_0\) and \(\alpha\in{\mathbb R}\), \(C_c^\infty({\mathbb R}^d)\) is dense in \(C 
  \def#1{n} 
  \def0{0} 
  \ifx#10\else^{n}\fi
_{w_{\alpha},\infty}({\mathbb R}^d)\) with respect to \(\|\cdot\|_{C 
  \def#1{n} 
  \def0{0} 
